def restore_snapshots(apps, schema_editor):
    """Восстановить старые поля из Reading при откате миграции."""
    alias = schema_editor.connection.alias
    Report = apps.get_model('reports_web', 'Report')
    Reading = apps.get_model('reports_web', 'Reading')
    for report in Report.objects.using(alias).all().iterator():
        rows = {row.metric_id: row for row in
                Reading.objects.using(alias).filter(report_id=report.pk)}
        values = {}
        for metric in ('temperature', 'humidity'):
            row = rows.get(metric)
            for field in ('value', 'minimum', 'maximum'):
                values[f'{metric}_{field}'] = (
                    getattr(row, field) if row else None
                )
            values[f'{metric}_normal'] = (
                row.status == 'НОРМА' if row else None
            )
        leak = rows.get('leak')
        values['leak_detected'] = bool(leak.value) if leak else None
        Report.objects.using(alias).filter(pk=report.pk).update(**values)


